class Solution {
    public double calculateTax(int[][] brackets,int income){
        double tax=0;
        int previous=0;
        for(int[] bracket:brackets){
            int taxable=Math.max(0,Math.min(income,bracket[0])-previous);
            tax+=taxable*bracket[1]/100.0;
            if(income<=bracket[0])break;
            previous=bracket[0];
        }
        return tax;
    }
}

